"""Turns the tombstone warning capture (docs/nosql/reference/capture/tombstones.py, JSON lines in
~/.cache/roll-nosql/capture/out/tombstones.jsonl) into src/tests/captured_tombstones.rs.

    python3 -I scripts/gen_tombstones.py [capture.jsonl]
"""
import json
import os
import sys

src = sys.argv[1] if len(sys.argv) > 1 else os.path.expanduser('~/.cache/roll-nosql/capture/out/tombstones.jsonl')
here = os.path.dirname(os.path.abspath(__file__))


def lit(s):
    return json.dumps(s, ensure_ascii=False)


out = [
    '//! Generated by `scripts/gen_tombstones.py` from the capture of',
    '//! `docs/nosql/reference/capture/tombstones.py` on cassandra:5.0.9. Do not edit.',
    '',
    '/// (page size, query, per page: rows and warnings).',
    'pub type Case = (Option<i32>, &\'static str, &\'static [(usize, &\'static [&\'static str])]);',
    '',
    'pub const CASES: &[Case] = &[',
]
for line in open(src):
    d = json.loads(line)
    fetch = 'None' if d['fetch'] is None else 'Some(%d)' % d['fetch']
    pages = ', '.join('(%d, &[%s])' % (p['rows'], ', '.join(lit(w) for w in p['warnings'])) for p in d['pages'])
    out.append('    (%s, %s, &[%s]),' % (fetch, lit(d['cql']), pages))
out.append('];')
open(os.path.join(here, '..', 'src', 'tests', 'captured_tombstones.rs'), 'w').write('\n'.join(out) + '\n')
